    const makeJob = (id, demoId, status, title, snapshot = true) => ({ id,demoId,highlightIds:['own-1'],options:structuredClone(defaults),status,stage:status==='queued'?'waiting for recording':undefined,createdAt:new Date(Date.now()-1000).toISOString(),outputs:title?[{file:'J:/CS2ClipStudio/temp/function-audit/'+id+'.mp4',bytes:12000000,title,highlightId:'own-1'}]:[],log:['Fixture log'],...(snapshot?{sourceSnapshot:source(demoId,demoId==='demo-orphan'?'Ancient':'Mirage')}:{}) });
