const nav = page => page.getByRole('navigation',{name:'Main navigation'});
async function go(page,name){await nav(page).getByRole('button',{name,exact:true}).click();}
async function match(page){await go(page,'Matches');await page.locator('.demo-item').first().click();await page.getByRole('checkbox',{name:'Select Personal triple',exact:true}).waitFor();}
async function exportOne(page){await match(page);await page.getByRole('checkbox',{name:'Select Personal triple',exact:true}).click();await page.getByRole('button',{name:/^Export 1/}).click();await page.getByRole('dialog',{name:'Make your clips'}).waitFor();}
async function openClip(page,title){await go(page,'Clips');await page.locator('.clip-card').filter({hasText:title}).click();await page.getByRole('button',{name:'Open source match',exact:true}).waitFor();}
async function test(name,run,viewport={width:1366,height:768},entry='') {
  if(process.env.AUDIT_CASE && !process.env.AUDIT_CASE.split('|').some(part=>name.includes(part)))return;
  const context=await browser.newContext({viewport});const page=await context.newPage();page.setDefaultTimeout(3500);
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  try {
    await fixture(page);await page.goto(server.resolvedUrls.local[0]+entry,{timeout:30000});await page.getByText('Make every moment').waitFor();await page.locator('.home-page .clip-card').first().waitFor();
    await run(page);assert.deepEqual(errors,[],'No uncaught page errors');const heapBytes=await page.evaluate(()=>performance.memory?.usedJSHeapSize??null);results.push({name,pass:true,heapBytes});console.log('PASS',name);
  } catch(e) {
    await page.screenshot({path:output+'/'+phase+'-'+name.replace(/[^a-z0-9]+/gi,'-')+'.png',fullPage:true}).catch(()=>{});
    results.push({name,pass:false,error:e.message,pageErrors:errors});console.log('FAIL',name,e.message.split('\n')[0]);
  } finally {await context.close();}
}

